<script setup lang="ts">
import { uiText } from "../uiText";
import {computed} from 'vue';
import type {Match,MatchTimeline} from '../../bindings/leaguepingo/internal/core/models';
import {clock} from '../analysisData';
import GameIcon from './GameIcon.vue';
import RunePage from './RunePage.vue';
const props=defineProps<{match:Match;timeline?:MatchTimeline|null;participantId?:number}>();
const purchases=computed(()=>{const groups:{time:number;items:number[]}[]=[];for(const e of props.timeline?.events??[]){if(e.participantId!==props.participantId||e.type!=='ITEM_PURCHASED'||e.itemId<=0)continue;const last=groups.at(-1);if(last&&Math.abs(last.time-e.timestamp)<15000)last.items.push(e.itemId);else groups.push({time:e.timestamp,items:[e.itemId]});}return groups;});
const transactions=computed(()=>(props.timeline?.events??[]).filter(e=>e.participantId===props.participantId&&['ITEM_SOLD','ITEM_DESTROYED','ITEM_UNDO'].includes(e.type)));
const skills=computed(()=>(props.timeline?.events??[]).filter(e=>e.participantId===props.participantId&&e.type==='SKILL_LEVEL_UP'&&e.skillSlot>=1&&e.skillSlot<=4));
</script>
<template><section class="match-build"><section><h3>{{ uiText.matchBuild.itemOrder }}<small>{{ uiText.matchBuild.orderHint }}</small></h3><div v-if="purchases.length" class="build-order"><div v-for="(group,index) in purchases" :key="index"><span><GameIcon v-for="(id,i) in group.items" :key="i" kind="items" :id="id" :size="30"/></span><small>{{clock(group.time)}}</small></div></div><p v-else class="build-empty">{{timeline?uiText.matchBuild.noPurchases:uiText.matchBuild.loadPurchases}}</p><details v-if="transactions.length" class="item-transactions"><summary>{{ uiText.matchBuild.removedCount(transactions.length) }}</summary><div v-for="(e,i) in transactions" :key="i"><time>{{clock(e.timestamp)}}</time><span>{{e.type==='ITEM_SOLD'?uiText.matchBuild.sold:e.type==='ITEM_DESTROYED'?uiText.matchBuild.removed:uiText.matchBuild.undone}}</span><template v-if="e.type==='ITEM_UNDO'"><GameIcon kind="items" :id="e.beforeId" :size="24"/><span>→</span><GameIcon kind="items" :id="e.afterId" :size="24"/></template><GameIcon v-else kind="items" :id="e.itemId" :size="24"/></div></details></section><section><h3>{{ uiText.matchBuild.skillOrder }}<small>{{ uiText.matchBuild.skillOrderHint }}</small></h3><ol v-if="skills.length" class="skill-order"><li v-for="(e,i) in skills" :key="i" :class="{ultimate:e.skillSlot===4}" :title="clock(e.timestamp)"><small>{{i+1}}</small><b>{{['','Q','W','E','R'][e.skillSlot]}}</b></li></ol><p v-else class="build-empty">{{timeline?uiText.matchBuild.noSkills:uiText.matchBuild.loadSkills}}</p></section><section><h3>{{ uiText.common.runes }}</h3><RunePage :match="match"/></section></section></template>
<style scoped>.match-build>section{padding:16px;border-bottom:1px solid var(--border);}.match-build>section:last-child{border:0;}.match-build h3{font-size:13px;margin:0 0 14px;}.match-build h3 small{font-size:11px;color:var(--muted);font-weight:400;margin-left:10px;}.build-order{display:flex;flex-wrap:wrap;gap:18px;}.build-order>div{position:relative;}.build-order>div+div:before{content:'›';position:absolute;left:-12px;top:7px;color:var(--muted);}.build-order>div>span{display:flex;gap:3px;}.build-order small{display:block;font-size:11px;color:var(--muted);text-align:center;margin-top:6px;}.item-transactions{margin-top:16px;font-size:11px;color:var(--muted);}.item-transactions summary{cursor:pointer;}.item-transactions>div{display:flex;align-items:center;gap:10px;margin-top:8px;}.item-transactions time{width:36px;font-variant-numeric:tabular-nums;}.build-empty{font-size:12px;color:var(--muted);line-height:1.6;}.skill-order{display:flex;flex-wrap:wrap;gap:5px;list-style:none;padding:0;margin:0;}.skill-order li{display:flex;flex-direction:column;gap:4px;text-align:center;}.skill-order small{font-size:11px;color:var(--muted);}.skill-order b{display:grid;place-items:center;width:26px;height:28px;font-size:12px;background:var(--raised);border:1px solid var(--border);border-radius:3px;}.skill-order .ultimate b{color:var(--accent);border-color:var(--accent);}</style>
